@spec keyQueue_spec  src=tests/specs/keyQueue_spec.lua  loc=188  cases=8

# Intent
  keyQueue holds one frame's key presses. The fill polls every key constant the ImGui shim
  carries, less the mouse and the modifier keys, and a claim removes what it returns -- so a
  press one reader acts on is gone for the next. These pin the enumeration and its cost (the
  second call separating a fresh press from an autorepeat is paid only for a key that answered),
  the exact modifier match with Mod_None standing in for an omitted mask, ownership declining
  every claimant but the owner, and held/mods reading live state under an owner.

# Helpers
  @fn newQueue()  @ 35-38
  @fn nameOf(value)  @ 40-43
  @fn polledKeys()  @ 46-50
      -- The keys the fill asked about, and the keys it should have asked about.
  @fn shimKeys()  @ 52-62

# Cases
  @case 'the fill polls every key constant on the shim, less the mouse and modifier keys'  [pure]  @ 66-77
  @case 'a press queues an entry carrying the frame modifiers, and a claim removes it'  [pure]  @ 81-93
  @case 'each fill replaces the last frame's entries'  [pure]  @ 97-105
  @case 'take matches the modifier mask exactly, an omitted mask meaning Mod_None'  [pure]  @ 109-118
  @case 'autorepeat rides on the entry, and only a key that answered costs the second call'  [pure]  @ 122-137
  @case 'takeAny claims the queue in key order'  [pure]  @ 141-152
  @case 'an owned queue declines every claimant but the owner'  [pure]  @ 156-169
  @case 'held and mods read live state, whoever owns the queue'  [pure]  @ 173-186

